BEGIN;
-- CERRO VERDE WEB · PRUEBA INTEGRAL 01
-- Contrato: escritorio productivo + estado actual + validación posterior contra corte 13/09.
-- La migración deja el padrón PRE-REVISIÓN en 94 unidades (50 VACÍO + 44 CARGADO).
-- El oráculo 69 = 40 VACÍO + 29 CARGADO NO se usa como semilla productiva.
-- IMPORTANTE: esta migración actúa exclusivamente sobre datos CERRO VERDE.

CREATE TABLE IF NOT EXISTS public.cerro_verde_arrastre_operativo(
 placa text PRIMARY KEY,
 ultima_entrega text,
 codigo_tracto text,
 codigo_carreta text,
 placa_carreta text,
 licencia text,
 conductor text,
 fecha_carga text,
 fecha_cierre_ciclo timestamptz,
 estado_base text NOT NULL DEFAULT 'ESTACIONADO VACIO',
 grupo_reporte text NOT NULL DEFAULT 'CAL VACIO',
 situacion text NOT NULL DEFAULT 'ESPERA_NUEVO_CICLO',
 monitoreo_previo text,
 observacion_previa text,
 origen text,
 activo boolean NOT NULL DEFAULT true,
 registrado_en timestamptz NOT NULL DEFAULT now(),
 actualizado_en timestamptz NOT NULL DEFAULT now(),
 fecha_salida_arrastre timestamptz,
 motivo_salida text,
 nueva_entrega text,
 payload jsonb NOT NULL DEFAULT '{}'::jsonb
);
ALTER TABLE public.cerro_verde_arrastre_operativo ADD COLUMN IF NOT EXISTS fecha_salida_arrastre timestamptz;
ALTER TABLE public.cerro_verde_arrastre_operativo ADD COLUMN IF NOT EXISTS motivo_salida text;
ALTER TABLE public.cerro_verde_arrastre_operativo ADD COLUMN IF NOT EXISTS nueva_entrega text;
CREATE INDEX IF NOT EXISTS cv_arrastre_activo_idx ON public.cerro_verde_arrastre_operativo(activo);
CREATE INDEX IF NOT EXISTS cv_arrastre_entrega_idx ON public.cerro_verde_arrastre_operativo(ultima_entrega);
ALTER TABLE public.cerro_verde_arrastre_operativo ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cerro_verde_arrastre_operativo FROM anon,authenticated;
GRANT ALL ON public.cerro_verde_arrastre_operativo TO service_role;

CREATE TABLE IF NOT EXISTS public.cerro_verde_revision_unidades(
 usuario text NOT NULL,
 placa text NOT NULL,
 revisada boolean NOT NULL DEFAULT true,
 orden_revision integer,
 actualizado_en timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(usuario,placa)
);
ALTER TABLE public.cerro_verde_revision_unidades ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cerro_verde_revision_unidades FROM anon,authenticated;
GRANT ALL ON public.cerro_verde_revision_unidades TO service_role;

-- 0) RESPALDO TRANSACCIONAL del estado que esta migración va a reemplazar.
CREATE TABLE IF NOT EXISTS public.cerro_verde_migracion_backups(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 etiqueta text NOT NULL,
 creado_en timestamptz NOT NULL DEFAULT now(),
 payload jsonb NOT NULL
);
ALTER TABLE public.cerro_verde_migracion_backups ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cerro_verde_migracion_backups FROM anon,authenticated;
GRANT ALL ON public.cerro_verde_migracion_backups TO service_role;
INSERT INTO public.cerro_verde_migracion_backups(etiqueta,payload)
SELECT 'PRE_PRUEBA_INTEGRAL_01', jsonb_build_object(
 'maestro_equipos',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.cerro_verde_maestro_equipos t),
 'maestro_conductores',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.cerro_verde_maestro_conductores t),
 'sap_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.sap_registros_staging t WHERE itinerario='CERRO VERDE'),
 'diario_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.seguimiento_staging t WHERE itinerario='CERRO VERDE' AND origen='DIARIO'),
 'sesion_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.seguimiento_sesion_web t WHERE itinerario='CERRO VERDE'),
 'grupo_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.cerro_verde_grupo_smcv t),
 'arrastre_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.cerro_verde_arrastre_operativo t),
 'revision_cv',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) FROM public.cerro_verde_revision_unidades t)
);

-- 1) MAESTRO COMPLETO. No se crean códigos artificiales PLACA-XXXXX.
DELETE FROM public.cerro_verde_maestro_equipos;
