DELETE FROM public.seguimiento_sesion_web w
WHERE w.itinerario='CERRO VERDE' AND NOT EXISTS(SELECT 1 FROM _cv_daily_seed d WHERE d.orden_carga=w.orden_carga);
DELETE FROM public.seguimiento_staging s
WHERE s.itinerario='CERRO VERDE' AND s.origen='DIARIO' AND NOT EXISTS(SELECT 1 FROM _cv_daily_seed d WHERE d.orden_carga=s.orden_carga);
UPDATE public.seguimiento_staging s SET payload=d.payload,observacion_migracion='PARIDAD ESCRITORIO · DETALLES 6'
FROM _cv_daily_seed d WHERE s.itinerario='CERRO VERDE' AND s.origen='DIARIO' AND s.orden_carga=d.orden_carga;
INSERT INTO public.seguimiento_staging(itinerario,origen,orden_carga,payload,observacion_migracion)
SELECT 'CERRO VERDE','DIARIO',d.orden_carga,d.payload,'PARIDAD ESCRITORIO · DETALLES 6'
FROM _cv_daily_seed d WHERE NOT EXISTS(SELECT 1 FROM public.seguimiento_staging s WHERE s.itinerario='CERRO VERDE' AND s.origen='DIARIO' AND s.orden_carga=d.orden_carga);

-- 4) Arrastre de escritorio como soporte histórico/operativo. NO define por sí solo el ENVIAR.
DELETE FROM public.cerro_verde_arrastre_operativo;
INSERT INTO public.cerro_verde_arrastre_operativo(
 placa,ultima_entrega,codigo_tracto,codigo_carreta,placa_carreta,licencia,conductor,fecha_carga,fecha_cierre_ciclo,
 estado_base,grupo_reporte,situacion,monitoreo_previo,observacion_previa,origen,activo,registrado_en,actualizado_en,
 fecha_salida_arrastre,motivo_salida,nueva_entrega,payload)
SELECT x.placa,x.ultima_entrega,x.codigo_tracto,x.codigo_carreta,x.placa_carreta,x.licencia,x.conductor,x.fecha_carga,
 CASE WHEN nullif(x.fecha_cierre_ciclo,'') IS NULL THEN NULL ELSE x.fecha_cierre_ciclo::timestamptz END,
 coalesce(nullif(x.estado_base,''),'ESTACIONADO VACIO'),coalesce(nullif(x.grupo_reporte,''),'CAL VACIO'),coalesce(nullif(x.situacion,''),'ESPERA_NUEVO_CICLO'),
 x.monitoreo_previo,x.observacion_previa,x.origen,x.activo,
 CASE WHEN nullif(x.registrado_el,'') IS NULL THEN now() ELSE x.registrado_el::timestamptz END,
 CASE WHEN nullif(x.actualizado_el,'') IS NULL THEN now() ELSE x.actualizado_el::timestamptz END,
 CASE WHEN nullif(x.fecha_salida_arrastre,'') IS NULL THEN NULL ELSE x.fecha_salida_arrastre::timestamptz END,
