PLACA":"BYW706/TQP975","CODIGO CARRETA":"20-T-336","ESTADO":"","FECHA DE CARGA":"2026-09-12 00:00:00","SALIDA DE BASE RACIEMSA":"","LLEGADA A CARACOTO":"","SALIDA DE CARACOTO":"","LLEGADA A BASE RACIEMSA":"","SALIDA DE BASE RACIEMSA CARGADO":"","INGRESO A SMCV":"","SALIDA DE SMCV":"","LLEGADA A BASE RACIEMSA VACIO":"","MONITOREO":"","OBSERVACION":"","ENTREGA SAP":"4113925335","TRANSPORTE SAP":"14203027","NRO PEDIDO SAP":"108111684","GUIA SAP":"110-0302078","GRE-R SAP":"G010-134679","TIMESTAMP INGRESO SAP":"2026-09-12 19:41:00","TIMESTAMP SALIDA SAP":"2026-09-12 20:42:00","PLACA TRACTO":"BYW706","PLACA CARRETA":"TQP975","MATERIAL SAP":"10950","DESCRIPCION MATERIAL SAP":"CAL VIVA A GRANEL (MOLIDA) INTICAL","CANTIDAD SAP":"30.59","ESTADO CICLO":"ABIERTO","FECHA ALTA SEGUIMIENTO":"2026-09-13 15:05:56.692000","FECHA CIERRE SEGUIMIENTO":"","ORIGEN REGISTRO":"SAP_INCREMENTAL","OBSERVACION SISTEMA":"ALTA AUTOMATICA DESDE SAP","CONTROL INTERNO PERNOCTE":"","INGRESO A PLANTA":"","SALIDA DE PLANTA":"","INGRESO A CARGUIO":"","SALIDA DE CARGUIO":""}},"activo":true}]$cv$::jsonb) x(codigo_tracto text,payload jsonb,activo boolean)
